(() => {
  "use strict";
  // Piloto 01 — runtime de plantilla fija.
  //
  // El sistema visual NO se escribe acá: es la página que el merchant diseñó y
  // aprobó, congelada en template-sources/piloto-pdp-01/index.html, saneada e
  // incrustada abajo. Este archivo sólo la monta e inyecta datos en sus slots.
  // No editar a mano: se regenera con scripts/build-piloto-pdp-01-template.js.
  const FIXED_TEMPLATE_SOURCE_BASE64 = "";

  // --- preview del editor ---------------------------------------------------
  const previewMode = /[?&]app=1/.test(location.search);
  const previewKey = "piloto-pdp-01-preview";
  // El editor reenvía el documento al abrir el iframe y después de cada edición.
  // La vista previa debe actualizarse en el lugar: una recarga borra el scroll,
  // interrumpe la selección y hace que el canvas parezca inestable.
  const sign = (payload) => JSON.stringify([payload?.data?.piloto_pdp_01 ?? null, payload?.urls ?? {}]);
  let rendered = null;
  let bridgeAbort = null;
  let timerFrame = null;
  const root = document.getElementById("piloto-pdp-01");

  if (previewMode && !window.TIENDAIQ_DATA) {
    try {
      const cached = JSON.parse(sessionStorage.getItem(previewKey) || "null");
      if (cached?.data) {
        rendered = sign(cached);
        window.TIENDAIQ_DATA = cached.data;
        window.TIENDAIQ_URLS = cached.urls || {};
        const source = cached.data?.piloto_pdp_01?.source_fields;
        window.TIENDAIQ_PRODUCT_TITLE = source?.title || "Vista previa";
        window.TIENDAIQ_VARIANTS = (source?.variants || []).map((variant) => ({ id: String(variant.id).split("/").pop(), adminId: variant.id, available: true, money: "" }));
      }
    } catch {}
  }
  function renderDocument(payload) {
  const data = payload?.data || window.TIENDAIQ_DATA;
  const doc = data?.piloto_pdp_01;
  if (!root || !doc?.content) return;
  // El iframe del editor es una maqueta de ancho fijo que se escala desde el
  // host. El documento nunca debe fabricar un segundo eje horizontal.
  if (previewMode) {
    document.documentElement.style.overflowX = "hidden";
    document.documentElement.style.width = "100%";
    document.body.style.overflowX = "hidden";
    document.body.style.width = "100%";
    document.body.style.margin = "0";
    root.style.maxWidth = "100%";
    root.style.overflowX = "hidden";
  }
  // Todos los manejadores pertenecen a este montaje. Al reemplazar el DOM se
  // cancela el anterior para que una edición no acumule listeners ni timers.
  bridgeAbort?.abort();
  bridgeAbort = new AbortController();
  const bridgeSignal = bridgeAbort.signal;
  if (timerFrame) cancelAnimationFrame(timerFrame);

  const c = doc.content;
  const ev = doc.evidence || {};
  const urls = payload?.urls || window.TIENDAIQ_URLS || {};
  const variants = Array.isArray(window.TIENDAIQ_VARIANTS) ? window.TIENDAIQ_VARIANTS : [];
  const image = (id) => urls[id] || "";

  // --- utilidades de binding -----------------------------------------------
  // El artefacto no declara [hidden]{display:none} — su CSS trae display de
  // autor en varias secciones —, así que ocultar con el atributo no alcanza.
  // Se oculta con estilo inline, que gana siempre.
  const hide = (node) => { if (node) node.style.setProperty("display", "none", "important"); };
  const show = (node) => { if (node) node.style.removeProperty("display"); };
  const text = (node, value) => {
    if (!node) return false;
    const v = value == null ? "" : String(value).trim();
    if (!v) { hide(node); return false; }
    node.textContent = v;
    return true;
  };
  const all = (scope, sel) => Array.from((scope || root).querySelectorAll(sel));
  const one = (scope, sel) => (scope || root).querySelector(sel);
  const conFuente = (bloque) => Boolean(bloque?.source?.kind && bloque?.source?.reference);
  const setImg = (node, url, alt) => {
    if (!node) return false;
    if (!url) { hide(node.closest("picture") || node); return false; }
    node.setAttribute("src", url);
    node.removeAttribute("data-tiq-remote-asset");
    node.setAttribute("alt", alt || "");
    return true;
  };
  // Rellena una lista de nodos con una lista de valores y saca los sobrantes.
  const fill = (nodes, values, apply) => {
    nodes.forEach((node, i) => {
      if (i < values.length) apply(node, values[i], i);
      else hide(node);
    });
  };

  // --- montaje --------------------------------------------------------------
  const bytes = Uint8Array.from(atob(FIXED_TEMPLATE_SOURCE_BASE64), (ch) => ch.charCodeAt(0));
  const source = new TextDecoder("utf-8").decode(bytes);
  const parsed = new DOMParser().parseFromString(source, "text/html");
  root.className = "";
  root.replaceChildren(...Array.from(parsed.body.childNodes));

  // --- galería --------------------------------------------------------------
  const gallery = [...new Set([c.media?.hero_media_id, ...(c.media?.gallery_media_ids || [])].filter((id) => image(id)))];
  const productTitle = window.TIENDAIQ_PRODUCT_TITLE || doc.source_fields?.title || "";
  const mainImage = one(root, ".phv4-main-image");
  setImg(mainImage, image(gallery[0]), productTitle);
  const thumbs = all(root, ".phv4-thumb");
  fill(thumbs, gallery, (button, id) => {
    button.setAttribute("data-tiq-media-id", id);
    button.setAttribute("data-phv4-image", image(id));
    setImg(one(button, "img"), image(id), productTitle);
    button.addEventListener("click", () => {
      const selected = button.getAttribute("data-tiq-media-id");
      const url = image(selected);
      if (!url || !mainImage) return;
      setImg(mainImage, url, productTitle);
      thumbs.forEach((item) => item.classList.toggle("is-active", item === button));
    });
  });

  // Las secciones posteriores conservan exactamente la composición aprobada,
  // pero sus fotos nunca viajan desde la plantilla de referencia. Se llenan
  // únicamente con media IDs del producto que Shopify entregó para esta página.
  const setEditorialImage = (selector, mediaId) => {
    const node = one(root, selector);
    if (!node) return;
    const url = image(mediaId);
    if (url) setImg(node, url, productTitle);
    else hide(node.closest("figure, .scp-media") || node);
  };
  setEditorialImage(".scp-compare-photo img", c.media?.comparison_media_id || gallery[1] || gallery[0]);
  setEditorialImage(".scp-faq-v3-media img", c.media?.gallery_media_ids?.[2] || gallery[2] || gallery[0]);
  const storyMedia = c.media?.story_media_ids?.length ? c.media.story_media_ids : gallery;
  // Una tienda puede tener una sola foto. En ese caso se reutiliza su propia
  // imagen en las cards editoriales antes que dejar huecos visuales o traer
  // una foto ajena a la tienda.
  const storyCards = c.stories?.cards || [];
  const storyImageMedia = storyMedia.length ? storyCards.map((_item, index) => storyMedia[index % storyMedia.length]) : [];
  fill(all(root, ".scp-story-image img"), storyImageMedia, (node, id) => setImg(node, image(id), productTitle));
  all(root, ".scp-story-product > img").forEach((node) => setImg(node, image(gallery[0]), productTitle));
  setEditorialImage(".scp-community-photo img", c.media?.community_media_id || storyMedia[0] || gallery[0]);
  // El comparativo permanece en su lugar. Sin una fuente cargada por el
  // merchant no compara ni promete: nombra de forma neutral los dos espacios
  // visuales de la composición aprobada.
  const comparison = ev.comparison;
  all(root, ".scp-compare-tags").forEach((tags) => {
    const labels = all(tags, "span");
    if (conFuente(comparison)) {
      text(labels[0], comparison.left_label || "Comparación");
      text(labels[1], comparison.right_label || productTitle || "Producto");
    } else {
      text(labels[0], "Detalles");
      text(labels[1], productTitle || "Producto");
    }
    show(tags);
  });

  // --- encabezado del buy box ----------------------------------------------
  text(one(root, ".phv4-panel h1") || one(root, "h1"), productTitle);
  text(one(root, ".phv4-claim"), c.hero?.claim);
  fill(all(root, ".phv4-check span"), c.hero?.bullets || [], (node, value) => { node.textContent = value; });
  const divider = one(root, ".phv4-divider");
  if (divider) {
    // El divisor usa pseudo-elementos para las líneas: sólo se cambia su texto.
    const propio = Array.from(divider.childNodes).find((n) => n.nodeType === 3 && n.textContent.trim());
    if (propio) propio.textContent = c.offer?.heading || "";
    else divider.textContent = c.offer?.heading || "";
  }

  // --- datos rápidos del producto ------------------------------------------
  const quickFacts = c.quick?.items || [];
  const quickDetails = all(root, ".phv4-details details");
  if (quickFacts.length) {
    fill(quickDetails, quickFacts, (node, item) => {
      text(one(node, "summary"), item.question);
      text(one(node, ".phv4-answer") || one(node, ".scp-answer") || one(node, "p") || one(node, "div:not(:first-child)"), item.answer);
    });
  } else all(root, ".phv4-details").forEach(hide);

  // --- packs ----------------------------------------------------------------
  const variantFor = (pack) => variants.find((v) => v.adminId === pack.variant_id) || null;
  const canBuy = (pack) => Boolean(pack?.variant?.available) && (!pack.variant.inventoryTracked || Number(pack.variant.inventoryQuantity) >= pack.quantity);
  const money = (variant, quantity) => {
    if (!variant?.money) return "";
    if (quantity === 1 || !Number.isFinite(Number(variant.price))) return variant.money;
    try {
      return new Intl.NumberFormat(document.documentElement.lang || undefined, {
        style: "currency", currency: variant.currency || window.Shopify?.currency?.active || "USD"
      }).format((Number(variant.price) * quantity) / 100);
    } catch { return variant.money; }
  };
  const packs = (c.offer?.packs || []).map((p) => ({ ...p, variant: variantFor(p) })).filter((p) => p.variant);
  let active = packs.find(canBuy) || packs[0] || null;

  const packNodes = all(root, ".phv4-pack");
  fill(packNodes, packs, (node, pack) => {
    node.setAttribute("data-tiq-pack", pack.id);
    text(one(node, ".phv4-pack-title"), pack.label);
    text(one(node, ".phv4-pack-sub"), pack.subtitle);
    text(one(node, ".phv4-pack-price"), money(pack.variant, pack.quantity));
    setImg(one(node, ".phv4-product-thumb"), image(gallery[0]), productTitle);
    all(node, ".phv4-pack-line img").forEach((img) => setImg(img, image(gallery[0]), ""));
    const radio = one(node, "input[type=radio]");
    if (radio) {
      radio.value = String(pack.quantity);
      radio.checked = pack === active;
      radio.disabled = !canBuy(pack);
      radio.addEventListener("change", () => { active = pack; refresh(); });
    }
    node.addEventListener("click", () => { active = pack; refresh(); });
  });

  const precio = one(root, ".phv4-price span") || one(root, ".phv4-price");
  const atc = one(root, ".phv4-atc");
  const atcPrice = one(root, "[data-phv4-price]");
  const setAtcLabel = (label) => {
    if (!atc) return;
    // La fuente se sanea antes de distribuirse, por lo que el texto original
    // del botón no puede sobrevivir. Conservamos el span dinámico del precio
    // y reemplazamos sólo su nodo de texto directo.
    const directText = Array.from(atc.childNodes).find((node) => node.nodeType === 3);
    if (directText) directText.textContent = `${label} — `;
    else atc.insertBefore(document.createTextNode(`${label} — `), atc.firstChild);
    atc.setAttribute("aria-label", label);
  };

  function refresh() {
    packNodes.forEach((node) => node.classList.toggle("is-selected", node.getAttribute("data-tiq-pack") === active?.id));
    if (precio && active) precio.textContent = money(active.variant, 1) || active.variant?.money || "";
    if (atc) {
      const ok = canBuy(active);
      atc.disabled = !ok;
      setAtcLabel(ok ? "Añadir al carrito" : "Sin stock");
      if (atcPrice) atcPrice.textContent = ok && active ? money(active.variant, active.quantity) : "";
    }
  }

  if (atc) {
    atc.addEventListener("click", async (event) => {
      event.preventDefault();
      // El canvas no es un storefront. En modo preview el botón conserva su
      // aspecto y su selección de pack, pero jamás llama a /cart ni mezcla un
      // error operativo dentro de la maqueta de la página.
      if (previewMode) return;
      if (!canBuy(active)) return;
      atc.disabled = true;
      try {
        const res = await fetch("/cart/add.js", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ items: [{ id: Number(active.variant.id), quantity: active.quantity }] })
        });
        if (!res.ok) throw new Error("cart");
        window.location.assign("/cart");
      } catch {
        atc.disabled = false;
        atc.textContent = "No se pudo agregar. Probá otra vez";
      }
    });
  }

  // --- secciones de contenido ----------------------------------------------
  const why = one(root, ".scp-why-copy");
  if (why) {
    text(one(why, ".scp-kicker"), c.why?.eyebrow);
    text(one(why, "h2"), c.why?.heading);
    text(one(why, ":scope > p:not(.scp-kicker)"), c.why?.body);
  }
  fill(all(root, ".scp-point > p"), c.why?.points || [], (node, value) => { node.textContent = value; });

  // La composición visual de las cards se conserva, pero no se transforma en
  // prueba social inventada: son fichas editoriales basadas sólo en el catálogo.
  const stories = c.stories;
  const storySection = one(root, ".scp-stories-v2");
  if (stories && storySection) {
    text(one(storySection, "h2"), stories.heading);
    text(one(storySection, ".scp-stories-sub"), stories.intro);
    fill(all(storySection, ".scp-story-card"), storyCards, (card, item) => {
      text(one(card, ".scp-story-meta b") || one(card, "b"), item.title);
      text(one(card, ".scp-story-copy > p"), item.body);
      text(one(card, ".scp-story-product small"), item.product_note);
      text(one(card, ".scp-story-product b"), productTitle);
    });
    // La franja superior conserva el espacio y se vuelve editorial hasta que
    // exista una métrica real. Las estrellas y la condición de verificada no
    // se muestran jamás sin una fuente del merchant.
    const storyRating = one(storySection, ".scp-stories-rating");
    if (conFuente(ev.rating)) {
      text(one(storyRating, "b"), `${ev.rating.value}/5 · ${ev.rating.count} valoraciones`);
      show(storyRating);
      all(storySection, ".scp-stars").forEach(show);
    } else {
      text(one(storyRating, "b"), "Conocé el producto");
      all(storySection, ".scp-stars, .scp-story-verified").forEach(hide);
      show(storyRating);
    }
    const rail = one(storySection, ".scp-stories-grid");
    const moveStories = (direction) => {
      const card = one(rail, ".scp-story-card");
      if (!rail || !card) return;
      const style = typeof window.getComputedStyle === "function" ? window.getComputedStyle(rail) : null;
      const gap = Number.parseFloat(style?.gap || "0") || 0;
      rail.scrollBy({ left: direction * (card.getBoundingClientRect().width + gap), behavior: "smooth" });
    };
    one(storySection, ".scp-story-prev")?.addEventListener("click", () => moveStories(-1));
    one(storySection, ".scp-story-next")?.addEventListener("click", () => moveStories(1));
  } else if (storySection) hide(storySection);

  const journey = one(root, ".scp-journey-head");
  if (journey) {
    text(one(journey, "h2"), c.timeline?.heading);
    text(one(journey, "p"), c.timeline?.intro);
  }
  const steps = all(root, ".scp-timeline > *");
  fill(steps, c.timeline?.steps || [], (node, step) => {
    text(one(node, ".scp-week"), step.label);
    text(one(node, "h3") || one(node, "strong"), step.heading);
    text(one(node, "p"), step.body);
  });

  const faqItems = c.faq?.items || [];
  const detalles = all(root, ".scp-faq-v3-list details");
  fill(detalles, faqItems, (node, item) => {
    text(one(node, "summary"), item.question);
    const cuerpo = one(node, "p") || one(node, "div:not(:first-child)");
    text(cuerpo, item.answer);
  });
  all(root, ".scp-faq h2, .scp-faq-v3 h2").forEach((h) => text(h, c.faq?.heading));
  text(one(root, ".scp-faq-v3-copy > p"), c.faq?.intro);

  const closing = c.closing;
  const closingSection = one(root, ".scp-community");
  if (closing && closingSection) {
    text(one(closingSection, ".scp-eyebrow"), closing.eyebrow);
    text(one(closingSection, "h2"), closing.heading);
    const closingParagraphs = all(closingSection, ".scp-community-copy > p").filter((node) => !node.classList.contains("scp-eyebrow") && !node.classList.contains("scp-disclaimer"));
    text(closingParagraphs[0], closing.body);
    text(closingParagraphs[1], closing.secondary_body);
    all(closingSection, ".scp-disclaimer").forEach(hide);
  } else if (closingSection) hide(closingSection);

  // El cierre de newsletter no depende de copy generado ni de una promesa
  // comercial. Se envía al endpoint estándar de Shopify con el contrato que
  // entiende el storefront, en vez de hacer POST a la URL del producto actual.
  const newsletter = one(root, ".scp-email-form");
  if (newsletter) {
    newsletter.setAttribute("action", "/contact#contact_form");
    newsletter.setAttribute("method", "post");
    const addHidden = (name, value) => {
      if (one(newsletter, `input[name="${name}"]`)) return;
      const input = document.createElement("input");
      input.type = "hidden"; input.name = name; input.value = value;
      newsletter.prepend(input);
    };
    addHidden("form_type", "customer");
    addHidden("utf8", "✓");
    text(one(root, ".scp-email-wrap h2"), c.newsletter?.heading || "Recibí novedades por email");
    text(one(root, ".scp-email-wrap > p"), c.newsletter?.body || "Novedades y recursos de la tienda.");
  }

  // Estas superficies requieren configuración Shopify que Piloto 01 todavía
  // no recibe (suscripciones, medios de pago y políticas por tienda). No se
  // dejan placeholders de la fuente aprobada que puedan parecer datos reales.
  all(root, ".phv4-subscribe, .phv4-payment-icons").forEach(hide);

  // --- evidencia y espacios del merchant ------------------------------------
  // Cada bloque de la plantilla siempre se conserva. La fuente verificable
  // decide si se muestra evidencia real; su ausencia activa una versión
  // editorial neutra, no un hueco ni una afirmación simulada.
  if (conFuente(ev.rating)) {
    all(root, ".phv4-rating-text").forEach((n) => { n.textContent = `${ev.rating.value}/5 · ${ev.rating.count} valoraciones`; });
    all(root, ".phv4-stars").forEach(show);
  } else {
    all(root, ".phv4-rating-text").forEach((n) => { n.textContent = "Información del producto"; });
    all(root, ".phv4-stars").forEach(hide);
    all(root, ".phv4-rating").forEach(show);
  }

  // Las cinco tarjetas forman parte de la composición aprobada. Cuando el
  // merchant aún no cargó reseñas, se muestran como fichas editoriales del
  // producto (sin estrellas, nombres ni "compra verificada" ficticios).
  // Cuando sí las completa en el editor, cada tarjeta conserva su propia foto
  // y texto: no se colapsan todas en una única reseña.
  const savedReviews = Array.isArray(ev.testimonials?.items) ? ev.testimonials.items : (conFuente(ev.testimonial) ? [ev.testimonial] : []);
  const editorialReviews = storyCards.length
    ? Array.from({ length: 5 }, (_item, index) => {
      const card = storyCards[index % storyCards.length];
      return { author: card.title || "Sobre este producto", text: card.body || c.why?.body || c.hero?.claim || "Revisá los detalles del producto antes de elegir.", media_id: storyImageMedia[index % Math.max(storyImageMedia.length, 1)] || gallery[0] };
    })
    : Array.from({ length: 5 }, () => ({ author: "Sobre este producto", text: c.why?.body || c.hero?.claim || "Revisá los detalles del producto antes de elegir.", media_id: gallery[0] }));
  const reviewCards = savedReviews.length ? savedReviews : editorialReviews;
  const slides = all(root, ".phv4-opinion-slide");
  slides.forEach((slide, index) => {
    const card = reviewCards[index % reviewCards.length];
    text(one(slide, ".phv4-review-copy p") || one(slide, "p"), card.text);
    text(one(slide, "cite") || one(slide, ".phv4-review-head strong"), card.author);
    const avatar = one(slide, ".phv4-avatar");
    const avatarUrl = image(card.media_id) || image(gallery[index % Math.max(gallery.length, 1)]);
    if (avatarUrl && avatar) avatar.style.backgroundImage = `url("${avatarUrl}")`;
    all(slide, ".phv4-verified, .phv4-review-stars").forEach(savedReviews.length ? show : hide);
    show(slide);
  });
  all(root, ".phv4-opinion-carousel, .phv4-review").forEach(show);

  // El diseño escribe la garantía con pseudo-elementos. La fuente canónica las
  // dejó como `content:attr(data-tiq-text)`, así que el texto se inyecta por
  // atributo: sin dato, attr() no renderiza nada y el bloque queda apagado.
  const cssText = (sel, value) => {
    const node = one(root, sel);
    if (!node) return;
    if (value) node.setAttribute("data-tiq-text", value);
    else node.removeAttribute("data-tiq-text");
  };
  if (conFuente(ev.guarantee)) {
    cssText(".phv4-guarantee-v2 h2, .phv4-guarantee h2", ev.guarantee.title);
    cssText(".phv4-guarantee-v2 p, .phv4-guarantee p", ev.guarantee.body);
  } else {
    cssText(".phv4-guarantee-v2 h2, .phv4-guarantee h2", "Información clara antes de comprar");
    cssText(".phv4-guarantee-v2 p, .phv4-guarantee p", "Revisá los detalles, variantes y políticas de esta tienda antes de finalizar tu compra.");
    all(root, ".phv4-guarantee-v2, .phv4-guarantee").forEach(show);
  }

  // La fuente original agregaba un contador ficticio con un script que se
  // reiniciaba en cada visita. El runtime crea la misma superficie sólo si
  // hace falta: con una fecha rastreable cuenta de verdad; si no, se presenta
  // como estado informativo, sin urgencia inventada.
  const ensureOfferTimer = () => {
    const panel = one(root, ".phv4-panel");
    if (!panel) return null;
    let timer = one(panel, ".phv4-offer-timer");
    if (!timer) {
      timer = document.createElement("aside");
      timer.className = "phv4-offer-timer";
      timer.innerHTML = '<svg viewBox="0 0 100 100" aria-hidden="true"><circle class="phv4-timer-track" cx="50" cy="50" r="44"></circle><circle class="phv4-timer-progress" cx="50" cy="50" r="44"></circle></svg><div class="phv4-timer-copy"><strong class="phv4-timer-value"></strong><span class="phv4-timer-caption"></span></div>';
      panel.insertBefore(timer, panel.firstChild);
    }
    return timer;
  };
  const timer = ensureOfferTimer();
  if (timer) {
    const deadline = conFuente(ev.offer) ? Date.parse(ev.offer.ends_at) : NaN;
    const value = one(timer, ".phv4-timer-value");
    const caption = one(timer, ".phv4-timer-caption");
    const progress = one(timer, ".phv4-timer-progress");
    if (Number.isFinite(deadline) && deadline > Date.now()) {
      const paint = () => {
        const remaining = Math.max(0, deadline - Date.now());
        const seconds = Math.ceil(remaining / 1000);
        if (value) value.textContent = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
        if (caption) { caption.textContent = ev.offer.label || "FINALIZA EN"; caption.setAttribute("data-tiq-text", ev.offer.label || "FINALIZA EN"); }
        if (progress) progress.style.strokeDashoffset = String(276.46 * (1 - Math.min(1, remaining / 86400000)));
        if (remaining) timerFrame = requestAnimationFrame(paint);
      };
      paint();
    } else {
      if (value) value.textContent = "";
      if (caption) { caption.textContent = "INFORMACIÓN"; caption.setAttribute("data-tiq-text", "INFORMACIÓN"); }
      if (progress) progress.style.strokeDashoffset = "0";
    }
    show(timer);
  }

  // --- puente de edición (sólo preview interno) ----------------------------
  // La tienda nunca recibe estas marcas. En el editor, cada superficie del
  // canvas comunica el mismo identificador que usa el árbol y el inspector.
  // Es la diferencia entre "ver una página" y editarla de verdad.
  if (previewMode) {
    const editorBlocks = {
      hero: { selector: ".phv4-gallery, .phv4-panel", label: "Información del producto" },
      offer: { selector: ".phv4-packs, .phv4-atc", label: "Oferta y packs" },
      quick: { selector: ".phv4-details", label: "Detalles del producto" },
      why: { selector: ".scp-why, .scp-why-copy", label: "Historia del producto" },
      stories: { selector: ".scp-stories-v2", label: "Beneficios destacados" },
      timeline: { selector: ".scp-journey-head, .scp-timeline", label: "Cómo se usa" },
      faq: { selector: ".scp-faq-v3, .scp-faq", label: "Preguntas frecuentes" },
      closing: { selector: ".scp-community", label: "Cierre" },
      newsletter: { selector: ".scp-email-wrap, .scp-email-form", label: "Newsletter" },
      evidence: { selector: ".phv4-rating, .phv4-opinion-carousel, .phv4-guarantee", label: "Carrusel de reseñas" }
    };
    Object.entries(editorBlocks).forEach(([id, block]) => {
      all(root, block.selector).forEach((node) => {
        node.setAttribute("data-tiq-editor-block", id);
        node.setAttribute("data-tiq-editor-label", block.label);
      });
    });

    const editorStyle = document.createElement("style");
    editorStyle.textContent = `
      #piloto-pdp-01{--tiq-editor-focus:#005bd3;--tiq-editor-focus-hover:rgba(0,91,211,.45)}
      #piloto-pdp-01 [data-tiq-editor-block]{cursor:pointer;outline:1px solid transparent;outline-offset:2px;transition:outline-color .12s ease}
      #piloto-pdp-01 [data-tiq-editor-block]:hover{outline-color:var(--tiq-editor-focus-hover)}
      #piloto-pdp-01 [data-tiq-editor-block].tiq-editor-active{position:relative;outline:2px solid var(--tiq-editor-focus)}
      #piloto-pdp-01 [data-tiq-editor-block].tiq-editor-active::before{content:attr(data-tiq-editor-label);position:absolute;z-index:20;top:-24px;left:-2px;padding:4px 7px;border-radius:3px;color:#fff;background:var(--tiq-editor-focus);font:600 11px/1 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:0;white-space:nowrap;pointer-events:none}
    `;
    root.prepend(editorStyle);

    root.addEventListener("click", (event) => {
      const block = event.target.closest("[data-tiq-editor-block]");
      if (!block) return;
      window.parent?.postMessage({ tiendaiqEditor: "select-block", blockId: block.dataset.tiqEditorBlock }, window.location.origin);
    }, { signal: bridgeSignal });
    window.addEventListener("message", (event) => {
      if (event.origin !== window.location.origin) return;
      if (event.data?.tiendaiqEditor !== "highlight-block") return;
      const id = event.data.blockId;
      // Una misma sección puede tener nodos anidados (por ejemplo, el bloque
      // de oferta contiene sus packs). El contorno debe señalar una superficie
      // lógica, no apilar etiquetas sobre cada hijo como un overlay técnico.
      all(root, "[data-tiq-editor-block]").forEach((node) => {
        const sameParent = node.parentElement?.closest(`[data-tiq-editor-block="${id}"]`);
        node.classList.toggle("tiq-editor-active", node.dataset.tiqEditorBlock === id && !sameParent);
      });
    }, { signal: bridgeSignal });
  }

  // --- red de seguridad -----------------------------------------------------
  // El saneador reemplaza todo el copy de origen por "Contenido del producto".
  // Lo que no quedó bindeado no puede llegar al comprador.
  all(root, "*").forEach((node) => {
    if (node.children.length) return;
    if (/Contenido del producto/.test(node.textContent || "")) hide(node.closest("li, article, div, p, span, h2, h3") || node);
  });
  // Imágenes que quedaron sin fuente real.
  all(root, "img[data-tiq-remote-asset], img:not([src]), img[src='']").forEach((img) => hide(img.closest("picture, figure, button, div") || img));

  refresh();
  }

  const initialPayload = { data: window.TIENDAIQ_DATA, urls: window.TIENDAIQ_URLS || {} };
  if (initialPayload.data?.piloto_pdp_01) {
    rendered = sign(initialPayload);
    renderDocument(initialPayload);
  }

  if (previewMode) {
    window.addEventListener("message", (event) => {
      if (event.origin !== window.location.origin) return;
      if (!event.data?.tiendaiq || !event.data?.data?.piloto_pdp_01) return;
      const incoming = sign(event.data);
      if (incoming === rendered) return;
      rendered = incoming;
      sessionStorage.setItem(previewKey, JSON.stringify({ data: event.data.data, urls: event.data.urls || {} }));
      renderDocument(event.data);
    });
  }
})();
